  "content": "1|import type { AgentMode, ToolResult } from '../../../shared/api/contracts/ai/agentTypes';
2|import type { AiCapabilityPackId } from '../../../shared/api/contracts/ai/capabilityPacks';
3|import { resolveToolNamesForCapabilityPackIds } from '../../../shared/api/contracts/ai/capabilityPacks';
4|import type { AiNativeToolGroup } from '../../../shared/api/contracts/ai/types';
5|import type { ToolExecutionContext } from '../agent/types';
6|import type { TurnExecutionProfile } from '../agent/turnExecutionProfile';
7|import { isLookupProfile } from '../agent/turnExecutionProfile';
8|
9|export type ToolParameterSchema = {
10|  type: 'object';
11|  properties: Record<string, { type: string; description?: string }>;
12|  required?: string[];
13|};
14|
15|export type NativeToolDefinition = {
16|  name: string;
17|  description: string;
18|  group: AiNativeToolGroup;
19|  parameters: ToolParameterSchema;
20|  execute: (args: Record<string, unknown>, context: ToolExecutionContext) => Promise<ToolResult>;
21|};
22|
23|export type McpToolDefinition = {
24|  name: string;
25|  description: string;
26|  serverId: string;
27|  originalName: string;
28|  allowedTools?: string[];
29|  parameters: ToolParameterSchema;
30|  execute: (args: Record<string, unknown>, context: ToolExecutionContext) => Promise<ToolResult>;
31|};
32|
33|export type RegisteredNativeTool = NativeToolDefinition & {
34|  source: 'native';
35|};
36|
37|export type RegisteredMcpTool = McpToolDefinition & {
38|  source: 'mcp';
39|};
40|
41|export type RegisteredTool = RegisteredNativeTool | RegisteredMcpTool;
42|
43|export type ListToolDefinitionsOptions = {
44|  /** When set, native tools are limited to this session's enabled built-in packs (TOK-14). */
45|  activePackIds?: readonly AiCapabilityPackId[];
46|};
47|
48|const ASK_ALLOWED_GROUPS = new Set<AiNativeToolGroup>([
49|  'standards',
50|  'search',
51|  'read',
52|  'context',
53|  'openapi',
54|]);
55|
56|const ASK_ALLOWED_EDGE_TOOLS = new Set(['list_server_functions', 'get_server_function', 'test_server_function']);
57|
58|const ASK_ALLOWED_GIT_TOOLS = new Set(['git_status', 'git_diff', 'git_log', 'git_show', 'git_blame']);
59|
60|const ASK_BLOCKED_TOOL_NAMES = new Set([
61|  'run_tests',
62|  'git_commit',
63|  'git_checkout',
64|  'git_branch',
65|  'draft_file_patch',
66|  'draft_server_function',
67|  'draft_component_layout',
68|  'prune_tool_observations',
69|]);
70|
71|export class ToolRegistry {
72|  private tools = new Map<string, RegisteredTool>();
73|
74|  constructor(
75|    private readonly config: {
76|      mode: AgentMode;
77|      allowedGroups: AiNativeToolGroup[];
78|      executionProfile?: TurnExecutionProfile;
79|    },
80|  ) {}
81|
82|  register(tool: NativeToolDefinition): void {
83|    this.tools.set(tool.name, { ...tool, source: 'native' });
84|  }
85|
86|  registerMcp(tool: McpToolDefinition): void {
87|    this.tools.set(tool.name, { ...tool, source: 'mcp' });
88|  }
89|
90|  /** V5 Phase P11 § V5-23 — lets a caller (e.g. `AgentOrchestrator`) classify trust/capability by provenance, not just tool name. */
91|  getToolSource(name: string): 'native' | 'mcp' | undefined {
92|    return this.tools.get(name)?.source;
93|  }
94|
95|  listDefinitions(
96|    options?: ListToolDefinitionsOptions,
97|  ): Array<Pick<RegisteredTool, 'name' | 'description' | 'parameters'>> {
98|    const packToolNames = options?.activePackIds?.length
99|      ? resolveToolNamesForCapabilityPackIds(options.activePackIds)
100|      : null;
101|
102|    return [...this.tools.values()]
103|      .filter((tool) => this.isToolAllowed(tool))
104|      .filter((tool) => {
105|        if (!packToolNames) return true;
106|        if (tool.source === 'mcp') return true;
107|        return packToolNames.has(tool.name);
108|      })
109|      .map(({ name, description, parameters }) => ({ name, description, parameters }));
110|  }
111|
112|  isToolAllowed(tool: RegisteredTool): boolean {
113|    if (this.config.mode === 'ask') {
114|      if (tool.source === 'mcp') return false;
115|      if (ASK_BLOCKED_TOOL_NAMES.has(tool.name) || tool.name.startsWith('draft_')) return false;
116|      if (tool.group === 'edge') return ASK_ALLOWED_EDGE_TOOLS.has(tool.name);
117|      if (tool.group === 'git') return ASK_ALLOWED_GIT_TOOLS.has(tool.name);
118|      return ASK_ALLOWED_GROUPS.has(tool.group);
119|    }
120|"
